db.sync:
function sync(doc, oldDoc) {
          // Validation
          if (doc.type === undefined) {
            throw({forbidden: "Document type must be specified"});
          }

          // Route documents based on type
          if (doc.type === "Project") {
            // Projects are shared with assigned users
            if (doc.assignedto) {
              for (var i = 0; i < doc.assignedto.length; i++) {
                channel(doc.assignedto[i]);
              }
            }
          } else if (doc.type === "Location" || doc.type === "VisualSection" || 
                     doc.type === "DynamicVisualSection" || doc.type === "LocationForm") {
            // Shared documents by company
            if (doc.companyIdentifier) {
              channel("company_" + doc.companyIdentifier);
            }
          } else if (doc.type === "DeckImage") {
            // Images can be accessed by the uploader and company users
            if (doc.uploadedBy) {
              channel(doc.uploadedBy);
            }
            if (doc.companyIdentifier) {
              channel("company_" + doc.companyIdentifier);
            }
          } else {
            // Default: channel by user
            channel(doc.createdby || "public");
          }

          // Track document changes
          access(doc.createdby || "public", doc._id);
        }
